310	func listDeleteUserMemoReferencedInboxIDs(ctx context.Context, tx *sql.Tx, userID int32, memoIDSet map[int32]struct{}) ([]int32, error) {
311		rows, err := tx.QueryContext(ctx, `
312			SELECT id, message
313			FROM inbox
314			WHERE sender_id <> `+deleteUserPlaceholder(1)+`
315				AND receiver_id <> `+deleteUserPlaceholder(2), userID, userID)
316		if err != nil {
317			return nil, err
318		}
319		defer rows.Close()
320	
321		inboxIDs := make([]int32, 0)
322		for rows.Next() {
323			var (
324				inboxID    int32
325				messageRaw []byte
326			)
327			if err := rows.Scan(&inboxID, &messageRaw); err != nil {
328				return nil, err
329			}
330			if len(messageRaw) == 0 {
